INSERT INTO investigation_materials (investigation_id, material_id, role, confidence, is_primary, evidence_quality, data_completeness, evidence_files, evidence_quote, notes) VALUES ('PSI-10', 'ethylene', 'fuel', 'high', true, 95, 85, '["PSI-10/Reports/PSI-10_Reports_FinalRpt_ACMEFlameDesign.pdf", "PSI-10/Raw Data/Reduced Gravity/1_normal_ethylene_flames_inferior_burner_1002", "PSI-10/Raw Data/Reduced Gravity/4_inverse_ethylene_flames_burner_1003"]'::jsonb, 'Except for the single propane (C3H8) test day previously mentioned, all ISS tests were conducted with the fuel ethylene (C2H4).', 'Primary flight fuel; normal and inverse spherical diffusion flames.');
INSERT INTO investigation_materials (investigation_id, material_id, role, confidence, is_primary, evidence_quality, data_completeness, evidence_files, evidence_quote, notes) VALUES ('PSI-10', 'propane', 'fuel', 'medium', false, 85, 75, '["PSI-10/Reports/PSI-10_Reports_FinalRpt_ACMEFlameDesign.pdf", "PSI-10/Raw Data/Reduced Gravity/3_normal_propane_flames_burner_1003"]'::jsonb, 'the first day of testing in the second round was carried out in the normal flame configuration, with propane (with or without nitrogen) flowing into an oxygen/nitrogen atmosphere.', 'One propane test day; not the main fuel.');
INSERT INTO investigation_materials (investigation_id, material_id, role, confidence, is_primary, evidence_quality, data_completeness, evidence_files, evidence_quote, notes) VALUES ('PSI-10', 'methane', 'planned_not_tested', 'low', false, 55, 45, '["PSI-10/Reports/PSI-10_Reports_FinalRpt_ACMEFlameDesign.pdf"]'::jsonb, 'Desired ISS testing with the fuel methane (CH4), inert carbon dioxide (CO2), and coflow flame configuration was not ...', 'Methane was planned but the reported ISS test campaign focused on ethylene/propane.');
INSERT INTO investigation_materials (investigation_id, material_id, role, confidence, is_primary, evidence_quality, data_completeness, evidence_files, evidence_quote, notes) VALUES ('PSI-100', 'sibal_fabric', 'test_material', 'high', true, 90, 85, '["PSI-100/Science Documents/PSI-100_Science Documents_SAFFIRE Objectives, Development and Status.pdf", "PSI-100/Science Documents/PSI-100_Science Documents_SAFFIRE-I and SAFFIRE-III Readme.docx"]'::jsonb, 'The sample material for SAFFIRE-I and SAFFIRE-III is a composite fabric consisting of cotton on a fiberglass substrate (75% cotton, 25% fiberglass by weight). It is called SIBAL cloth ...', 'Large-scale fire growth at 30 cm/s airflow.');
INSERT INTO investigation_materials (investigation_id, material_id, role, confidence, is_primary, evidence_quality, data_completeness, evidence_files, evidence_quote, notes) VALUES ('PSI-100', 'cotton', 'constituent', 'high', false, 85, 80, '["PSI-100/Science Documents/PSI-100_Science Documents_SAFFIRE Objectives, Development and Status.pdf"]'::jsonb, '75% cotton, 25% fiberglass by weight', 'Combustible constituent of SIBAL.');
